INSERT INTO `infra_data_interface` VALUES (35, '用户分页查询', '', 'system_users', 'internal', NULL, 1, 0, 0, 'select * from system_users where mobile like CONCAT(#{mobile}, \'%\')\nLIMIT #{offsetSize},#{pageSize}', 1, '', NULL, 0, '[{\"name\":\"mobile\",\"label\":\"手机号\",\"type\":\"STRING\",\"required\":true,\"defaultValue\":\"\",\"remark\":null}]', '// 把查询结果转成下拉框需要的 { value, label } 结构\nreturn data.list.map(function (row) {\n  return { value: row.nickname, label: row.username };\n});', 'SELECT', b'0', 20, 1, '', '1', '2026-08-31 00:04:20', '1', '2026-09-01 05:38:47', b'0', 1);
