INSERT INTO `infra_data_interface` VALUES (40, '角色API', '', 'role_api', 'internal', NULL, 3, 0, 0, '{\"method\":\"GET\",\"url\":\"/admin-api/system/role/page\",\"queryParams\":[{\"key\":\"pageNo\",\"value\":\"#{pageNo}\",\"description\":\"\",\"enabled\":true},{\"key\":\"pageSize\",\"value\":\"#{pageSize}\",\"description\":\"\",\"enabled\":true}],\"headers\":[],\"bodyType\":\"none\",\"bodyParams\":[],\"bodyContent\":\"\"}', 0, '', '', 1, '[{\"name\":\"pageNo\",\"label\":\"页码\",\"type\":\"INT\",\"required\":false,\"defaultValue\":\"1\",\"remark\":null},{\"name\":\"pageSize\",\"label\":\"条数\",\"type\":\"INT\",\"required\":false,\"defaultValue\":\"1\",\"remark\":null}]', '// 把查询结果转成下拉框需要的 { value, label } 结构\r\nreturn {\r\n  code: data.code,\r\n  data: {\r\n    list: data.data.list.map(function (row) {\r\n      return { label: row.name, value: row.code };\r\n    })\r\n  }\r\n};', '', b'0', 8, 1, '', '1', '2026-09-01 05:37:38', '1', '2026-09-01 05:46:04', b'0', 1);
