ic\": \"AND\", \"items\": [{\"field\": \"trip_days\", \"operator\": \"BETWEEN\", \"valueType\": \"CONST\", \"value\": [1, 30]}]}, \"message\": \"出差天数须在 1~30 天之间\", \"enabled\": true, \"fields\": [\"trip_days\"]}, {\"id\": \"r_cabin_required\", \"name\": \"坐飞机必须选舱位\", \"must\": {\"logic\": \"AND\", \"items\": [{\"field\": \"cabin_class\", \"operator\": \"NOT_EMPTY\", \"valueType\": \"CONST\"}]}, \"message\": \"交通方式为飞机时，必须选择舱位等级\", \"enabled\": true, \"when\": {\"logic\": \"AND\", \"items\": [{\"field\": \"transport\", \"operator\": \"IN\", \"valueType\": \"CONST\", \"value\": [\"AIR\"]}]}, \"fields\": [\"cabin_class\"]}, {\"id\": \"r_hotel_city\", \"name\": \"订酒店必须填入住城市\", \"must\": {\"logic\": \"AND\", \"items\": [{\"field\": \"hotel_city\", \"operator\": \"NOT_EMPTY\", \"valueType\": \"CONST\"}]}, \"message\": \"勾选了「需要订酒店」时，入住城市必填\", \"enabled\": true, \"when\": {\"logic\": \"AND\", \"items\": [{\"field\": \"need_hotel\", \"operator\": \"EQ\", \"valueType\": \"CONST\", \"value\": 1}]}, \"fields\": [\"hotel_city\"]}, {\"id\": \"r_contact\", \"name\": \"手机与座机至少填一个\", \"must\": {\"logic\": \"AND\", \"items\": [{\"field\": \"telephone\", \"operator\": \"NOT_EMPTY\", \"valueType\": \"CONST\"}]}, \"message\": \"手机号与座机至少填写一个\", \"enabled\": true, \"when\": {\"logic\": \"AND\", \"items\": [{\"field\": \"mobile\", \"operator\": \"EMPTY\", \"valueType\": \"CONST\"}]}, \"fields\": [\"mobile\", \"telephone\"]}, {\"id\": \"r_budget_quota\", \"name\": \"预算不得超过部门额度\", \"must\": {\"logic\": \"AND\", \"items\": [{\"field\": \"budget_amount\", \"operator\": \"LE\", \"valueType\": \"FIELD\", \"value\": \"dept_quota\"}]}, \"message\": \"预算金额不得超过部门额度\", \"enabled\": true, \"fields\": [\"budget_amount\", \"dept_quota\"]}, {\"id\": \"r_reason_required\", \"name\": \"长差或空中出行且金额较大时必须说明\", \"must\": {\"logic\": \"AND\", \"items\": [{\"field\": \"reason\", \"operator\": \"NOT_EMPTY\", \"valueType\": \"CONST\"}]}, \"message\": \"坐飞机或超过 7 天，且预算超过 1 万元时，必须填写特别说明\", \"enabled\": true, \"when\": 