{\\\"title\\\": \\\"勾上下面这个开关再提交：beforeSubmit 会弹一个确认框，请【不要点击】。10 秒后钩子超时，按表单属性配置的「阻断」处理，提交被拒。默认阻断的理由是 —— 超时意味着校验没跑完，放行等于静默跳过校验。\\\", \\\"type\\\": \\\"info\\\", \\\"closable\\\": false}}\",\"{\\\"type\\\": \\\"switch\\\", \\\"field\\\": \\\"slow_hook\\\", \\\"title\\\": \\\"演示超时阻断\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0017\\\", \\\"name\\\": \\\"ref_demo0017\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"switch\\\", \\\"props\\\": {\\\"activeValue\\\": 1, \\\"inactiveValue\\\": 0}}\",\"{\\\"type\\\": \\\"textarea\\\", \\\"field\\\": \\\"remark\\\", \\\"title\\\": \\\"备注\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0018\\\", \\\"name\\\": \\\"ref_demo0018\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"textarea\\\", \\\"props\\\": {\\\"rows\\\": 2}}\"]', '{\"columns\": [{\"field\": \"contract_no\", \"label\": \"合同编号\", \"width\": 150, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": true, \"sortable\": true}, {\"field\": \"contract_name\", \"label\": \"合同名称\", \"width\": 220, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"party_b\", \"label\": \"乙方\", \"width\": 180, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"amount\", \"label\": \"合同金额\", \"width\": 140, \"widthType\": \"min\", \"align\": \"right\", \"fixed\": false, \"sortable\": true, \"formatter\": {\"type\": \"NUMBER\", \"precision\": 2, \"thousands\": true}}, {\"field\": \"legal_checked\", \"label\": \"已法审\", \"width\": 90, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"BOOLEAN\"}}, {\"field\": \"risk_level\", \"label\": \"风险等级\", \"width\": 110, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"TAG\", \"dictType\": \"test_demo_verify_risk\"}}, {\"field\": \"sign_date\", \"label\": \"签订日期\", \"width\": 120, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"DATE\"}}, {\"field\": \"expire_date\", \"label\": \"到期日期\", \"width\": 120, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"DATE\"}}, {\"field\": \"owner_name\", \"label\": \"负责人\", \"width\": 100, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"bill_status\", \"label\": \"状态\", \"width\": 110, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"TAG\", \"dictType\": \"test_demo_bill_status\"}}], \"searchItems\": [{\"field\": \"contract_no\", \"label\": \"合同编号\", \"widget\": \"TEXT\", \"operator\": \"LIKE\"}, {\"field\": \"contract_name\", \"label\": \"合同名称\", \"widget\": \"TEXT\", \"operator\": \"LIKE\"}, {\"field\": \"risk_level\", \"label\": \"风险等级\", \"widget\": \"SELECT\", \"operator\": \"EQ\", \"dictType\": \"test_demo_verify_risk\"}, {\"field\": \"amount\", \"label\": \"合同金额\", \"widget\": \"NUMBER_RANGE\", \"operator\": \"BETWEEN\"}, {\"field\": \"sign_date\", \"label\": \"签订日期\", \"widget\": \"DATE_RANGE\", \"operator\": \"BETWEEN\"}], \"pagination\": {\"enabled\": true, \"pageSize\": 20}, \"defaultSort\": {\"field\": \"contract_no\", \"order\": \"asc\"}, \"operationColumn\": {\"show\": true, \"label\": \"操作\", \"width\": 260, \"fixed\": \"right\", \"buttons\": [{\"key\": \"create\", \"label\": \"新增\", \"icon\": \"ep:plus\", \"show\": true}, {\"key\": \"edit\", \"label\": \"编辑\", \"icon\": null, \"show\": true}, {\"key\": \"detail\", \"label\": \"详情\", \"icon\": null, \"show\": true}, {\"key\": \"changeLog\", \"label\": \"变更记录\", \"icon\": null, \"show\": true}, {\"key\": \"delete\", \"label\": \"删除\", \"icon\": null, \"show\": true}]}, \"showSummary\": true, \"summaryColumns\": [\"amount\"], \"export\": {\"enabled\": true}}', 0, 'test_demo_verify_contract', 'id', '{\"mainTable\": \"test_demo_verify_contract\", \"mainPk\": \"id\", \"pkStrategy\": \"SNOWFLAKE\", \"logicDelete\": {\"enabled\": true, \"column\": \"deleted\", \"deletedValue\": \"1\", \"normalValue\": \"0\", \"valueType\": \"NUMBER\"}, \"optimisticLock\": {\"enabled\": true, \"column\": \"version\"}, \"autoFill\": {\"creatorColumn\": \"creator\", \"creatorMode\": \"AUTO\", \"createTimeColumn\": \"create_time\", \"createTimeMode\": \"AUTO\", \"updaterColumn\": \"updater\", \"updaterMode\": \"AUTO\", \"updateTimeColumn\": \"update_time\", \"updateTimeMode\": \"AUTO\"}, \"changeLog\": {\"enabled\": true}, \"fieldMapping\": {\"contract_no\": {\"table\": \"test_demo_verify_contract\", \"column\": \"contract_no\", \"jdbcType\": \"VARCHAR\"}, \"contract_name\": {\"table\": \"test_demo_verify_contract\", \"column\": \"contract_name\", \"jdbcType\": \"VARCHAR\"}, \"party_b\": {\"table\": \"test_demo_verify_contract\", \"column\": \"party_b\", \"jdbcType\": \"VARCHAR\"}, \"amount\": {\"table\": \"test_demo_verify_contract\", \"column\": \"amount\", \"jdbcType\": \"DECIMAL\"}, \"legal_checked\": {\"table\": \"test_demo_verify_contract\", \"column\": \"legal_checked\", \"jdbcType\": \"TINYINT\"}, \"risk_level\": {\"table\": \"test_demo_verify_contract\", \"column\": \"risk_level\", \"jdbcType\": \"VARCHAR\"}, \"sign_date\": {\"table\": \"test_demo_verify_contract\", \"column\": \"sign_date\", \"jdbcType\": \"DATE\"}, \"expire_date\": {\"table\": \"test_demo_verify_contract\", \"column\": \"expire_date\", \"jdbcType\": \"DATE\"}, \"owner_name\": {\"table\": \"test_demo_verify_contract\", \"column\": \"owner_name\", \"jdbcType\": \"VARCHAR\"}, \"slow_hook\": {\"table\": \"test_demo_verify_contract\", \"column\": \"slow_hook\", \"jdbcType\": \"TINYINT\"}, \"bill_status\": {\"table\": \"test_demo_verify_contract\", \"column\": \"bill_status\", \"jdbcType\": \"VARCHAR\"}, \"remark\": {\"table\": \"test_demo_verify_contract\", \"column\": \"remark\", \"jdbcType\": \"VARCHAR\"}}}', 1, 2, 2682, NULL, 17, '前端脚本四钩子全覆盖：默认值、即时提示、提交前组合校验与二次确认、超时阻断；并演示「内核必填先于 beforeSubmit」这条坑', 'MANUAL', b'0', NULL, 0, '1', '2026-09-13 00:06:43', '1', '2026-10-15 23:28:09', b'0', NULL, 1, '{\"onLoad\": \"// 新建时补默认值。已有记录不覆盖 —— onLoad 排在数据回填之后执行\\nif (!getFieldValue(\'bill_status\')) {\\n  setFieldValue(\'bill_status\', \'DRAFT\');\\n}\\nif (!getFieldValue(\'risk_level\')) {\\n  setFieldValue(\'risk_level\', \'LOW\');\\n}\\n// 金额还没填时先把法审那一栏收起来，填了金额再亮出来\\nvar amount = Number(getFieldValue(\'amount\') || 0);\\nsetVisible(\'legal_checked\', amount > 0);\", \"onFieldChange\": \"// changedField 是沙箱注入的裸标识符，只有本钩子有值\\nif (changedField === \'amount\') {\\n  var amount = Number(getFieldValue(\'amount\') || 0);\\n  setVisible(\'legal_checked\', amount > 0);\\n  if (amount > 500000) {\\n    message.warning(\'金额超过 50 万元，提交前必须勾选「已法审」\');\\n  }\\n}\\nif (changedField === \'risk_level\' && getFieldValue(\'risk_level\') === \'HIGH\') {\\n  message.warning(\'高风险合同：请确认已附风险评估说明\');\\n}\", \"beforeSubmit\": \"// ⚠️ 内核的必填校验【先于】本钩子。合同名称没填时这里根本不会执行，\\n//    所以不要指望在这里补必填提示 —— 那段代码永远跑不到\\nvar amount = Number(getFieldValue(\'amount\') || 0);\\nvar legal = getFieldValue(\'legal_checked\');\\nvar risk = getFieldValue(\'risk_level\');\\nvar problems = [];\\n\\nif (amount > 500000 && !(legal === 1 || legal === true)) {\\n  problems.push(\'金额超过 50 万元，必须先完成法务审核\');\\n}\\n// 这一条声明式规则表达不了：它要求的是「先走一个线下流程」，不是字段之间的关系\\nif (risk === \'HIGH\' && amount > 100000) {\\n  problems.push(\'高风险且金额超过 10 万元，需先完成线下评审\');\\n}\\nvar sign = getFieldValue(\'sign_date\');\\nvar expire = getFieldValue(\'expire_date\');\\nif (sign && expire && new Date(expire).getTime() <= new Date(sign).getTime()) {\\n  problems.push(\'到期日期必须晚于签订日期\');\\n}\\n\\nif (problems.length > 0) {\\n  message.error(problems.join(\'；\'));\\n  return false;\\n}\\n\\n// 演示超时：勾上开关后弹一个确认框并请你【不要点】。\\n// 10 秒内没有结果，钩子超时，按表单属性里配的「阻断」处理\\nif (getFieldValue(\'slow_hook\') === 1) {\\n  return message.confirm(\'演示超时阻断：请不要点击，等待 10 秒看看会发生什么\');\\n}\\n\\n// 大额合同二次确认。confirm 返回 Promise<boolean>，直接 return 即可\\nif (amount > 500000) {\\n  return message.confirm(\'合同金额 \' + utils.formatMoney(amount) + \' 元，确认提交？\');\\n}\\nreturn true;\", \"afterSubmit\": \"// afterSubmit 出错只记日志，不影响已经成功的提交 ——\\n// 四个钩子里只有 beforeSubmit 是「出错即阻断」\\nmessage.success(\'合同「\' + (getFieldValue(\'contract_name\') || \'\') + \'」已提交\');\"}', 1, '[{\"id\": \"r_expire\", \"name\": \"到期日期必须晚于签订日期\", \"must\": {\"logic\": \"AND\", \"items\": [{\"field\": \"expire_date\", \"operator\": \"GT\", \"valueType\": \"FIELD\", \"value\": \"sign_date\"}]}, \"message\": \"到期日期必须晚于签订日期\", \"enabled\": true, \"fields\": [\"expire_date\", \"sign_date\"]}, {\"id\": \"r_legal\", \"name\": \"大额合同必须已法审\", \"must\": {\"logic\": \"AND\", \"items\": [{\"field\": \"legal_checked\", \"operator\": \"EQ\", \"valueType\": \"CONST\", \"value\": 1}]}, \"message\": \"金额超过 50 万元的合同，必须先完成法务审核\", \"enabled\": true, \"when\": {\"logic\": \"AND\", \"items\": [{\"field\": \"amount\", \"operator\": \"GT\", \"valueType\": \"CONST\", \"value\": 500000}]}, \"fields\": [\"legal_checked\", \"amount\"]}]', NULL, NULL, NULL);
INSERT INTO `infra_form_design` VALUES (3700, '校验示例7-服务端扩展点', 'test_demo_verify_staff', 'business', 2, 1, '{\"form\":{\"labelWidth\":\"140px\",\"labelPosition\":\"right\",\"size\":\"default\"}}', '[\"{\\\"type\\\": \\\"elAlert\\\", \\\"field\\\": \\\"v_tip\\\", \\\"title\\\": \\\"提示\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0001\\\", \\\"name\\\": \\\"ref_demo0001\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"elAlert\\\", \\\"props\\\": {\\\"title\\\": \\\"本表单的扩展模式是「服务端扩展点」，逻辑写在 Java 里。试一下：身份证末位改成别的数字（格式仍合法）再提交 —— 会被校验码算法拦住；用已有的身份证新增一条 —— 会被查库查重拦住；工号留空 —— 服务端会生成并写回。\\\", \\\"type\\\": \\\"warning\\\", \\\"closable\\\": false}}\",\"{\\\"type\\\": \\\"fcTitle\\\", \\\"field\\\": \\\"g_base\\\", \\\"title\\\": \\\"一、基本信息\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0002\\\", \\\"name\\\": \\\"ref_demo0002\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"fcTitle\\\", \\\"props\\\": {\\\"title\\\": \\\"一、基本信息\\\", \\\"collapsible\\\": true}}\",\"{\\\"type\\\": \\\"input\\\", \\\"field\\\": \\\"staff_no\\\", \\\"title\\\": \\\"工号\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0003\\\", \\\"name\\\": \\\"ref_demo0003\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"input\\\", \\\"props\\\": {\\\"disabled\\\": true, \\\"placeholder\\\": \\\"留空即可，由服务端生成\\\"}}\",\"{\\\"type\\\": \\\"input\\\", \\\"field\\\": \\\"staff_name\\\", \\\"title\\\": \\\"姓名\\\", \\\"$required\\\": true, \\\"_fc_id\\\": \\\"id_demo0004\\\", \\\"name\\\": \\\"ref_demo0004\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"input\\\"}\",\"{\\\"type\\\": \\\"input\\\", \\\"field\\\": \\\"id_card\\\", \\\"title\\\": \\\"身份证\\\", \\\"$required\\\": true, \\\"_fc_id\\\": \\\"id_demo0005\\\", \\\"name\\\": \\\"ref_demo0005\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"input\\\", \\\"props\\\": {\\\"validateRules\\\": [{\\\"type\\\": \\\"BUILTIN\\\", \\\"patternKey\\\": \\\"ID_CARD\\\", \\\"enabled\\\": true}], \\\"placeholder\\\": \\\"格式由正则判，最后一位的校验码由服务端算\\\"}}\",\"{\\\"type\\\": \\\"select\\\", \\\"field\\\": \\\"gender\\\", \\\"title\\\": \\\"性别\\\", \\\"$required\\\": true, \\\"_fc_id\\\": \\\"id_demo0006\\\", \\\"name\\\": \\\"ref_demo0006\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"select\\\", \\\"props\\\": {\\\"dictSource\\\": {\\\"dictType\\\": \\\"test_demo_verify_gender\\\", \\\"valueType\\\": \\\"str\\\"}}}\",\"{\\\"type\\\": \\\"input\\\", \\\"field\\\": \\\"mobile\\\", \\\"title\\\": \\\"手机号\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0007\\\", \\\"name\\\": \\\"ref_demo0007\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"input\\\", \\\"props\\\": {\\\"validateRules\\\": [{\\\"type\\\": \\\"BUILTIN\\\", \\\"patternKey\\\": \\\"MOBILE\\\", \\\"enabled\\\": true}]}}\",\"{\\\"type\\\": \\\"fcTitle\\\", \\\"field\\\": \\\"g_job\\\", \\\"title\\\": \\\"二、入职信息（状态机约束）\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0008\\\", \\\"name\\\": \\\"ref_demo0008\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"fcTitle\\\", \\\"props\\\": {\\\"title\\\": \\\"二、入职信息（状态机约束）\\\", \\\"collapsible\\\": true}}\",\"{\\\"type\\\": \\\"input\\\", \\\"field\\\": \\\"dept_name\\\", \\\"title\\\": \\\"部门\\\", \\\"$required\\\": true, \\\"_fc_id\\\": \\\"id_demo0009\\\", \\\"name\\\": \\\"ref_demo0009\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"input\\\"}\",\"{\\\"type\\\": \\\"input\\\", \\\"field\\\": \\\"post_name\\\", \\\"title\\\": \\\"岗位\\\", \\\"$required\\\": true, \\\"_fc_id\\\": \\\"id_demo0010\\\", \\\"name\\\": \\\"ref_demo0010\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"input\\\"}\",\"{\\\"type\\\": \\\"datePicker\\\", \\\"field\\\": \\\"entry_date\\\", \\\"title\\\": \\\"入职日期\\\", \\\"$required\\\": true, \\\"_fc_id\\\": \\\"id_demo0011\\\", \\\"name\\\": \\\"ref_demo0011\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"datePicker\\\", \\\"props\\\": {\\\"type\\\": \\\"date\\\", \\\"placeholder\\\": \\\"不得早于一年前；员工转正后这一栏就不允许再改了\\\"}}\",\"{\\\"type\\\": \\\"inputNumber\\\", \\\"field\\\": \\\"probation_months\\\", \\\"title\\\": \\\"试用期（月）\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0012\\\", \\\"name\\\": \\\"ref_demo0012\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"inputNumber\\\", \\\"props\\\": {\\\"precision\\\": 0, \\\"min\\\": 0, \\\"max\\\": 12, \\\"placeholder\\\": \\\"留空默认 3 个月，由扩展点补\\\"}}\",\"{\\\"type\\\": \\\"switch\\\", \\\"field\\\": \\\"regular_flag\\\", \\\"title\\\": \\\"是否已转正\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0013\\\", \\\"name\\\": \\\"ref_demo0013\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"switch\\\", \\\"props\\\": {\\\"activeValue\\\": 1, \\\"inactiveValue\\\": 0}}\",\"{\\\"type\\\": \\\"select\\\", \\\"field\\\": \\\"bill_status\\\", \\\"title\\\": \\\"单据状态\\\", \\\"$required\\\": true, \\\"_fc_id\\\": \\\"id_demo0014\\\", \\\"name\\\": \\\"ref_demo0014\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"select\\\", \\\"props\\\": {\\\"dictSource\\\": {\\\"dictType\\\": \\\"test_demo_bill_status\\\", \\\"valueType\\\": \\\"str\\\"}}}\",\"{\\\"type\\\": \\\"textarea\\\", \\\"field\\\": \\\"remark\\\", \\\"title\\\": \\\"备注\\\", \\\"$required\\\": false, \\\"_fc_id\\\": \\\"id_demo0015\\\", \\\"name\\\": \\\"ref_demo0015\\\", \\\"display\\\": true, \\\"hidden\\\": false, \\\"_fc_drag_tag\\\": \\\"textarea\\\", \\\"props\\\": {\\\"rows\\\": 2}}\"]', '{\"columns\": [{\"field\": \"staff_no\", \"label\": \"工号\", \"width\": 120, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": true, \"sortable\": true}, {\"field\": \"staff_name\", \"label\": \"姓名\", \"width\": 100, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"id_card\", \"label\": \"身份证\", \"width\": 190, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"gender\", \"label\": \"性别\", \"width\": 80, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"DICT\", \"dictType\": \"test_demo_verify_gender\"}}, {\"field\": \"dept_name\", \"label\": \"部门\", \"width\": 130, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"post_name\", \"label\": \"岗位\", \"width\": 130, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"entry_date\", \"label\": \"入职日期\", \"width\": 120, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": true, \"formatter\": {\"type\": \"DATE\"}}, {\"field\": \"probation_months\", \"label\": \"试用期(月)\", \"width\": 110, \"widthType\": \"min\", \"align\": \"right\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"NUMBER\", \"precision\": 0}}, {\"field\": \"regular_flag\", \"label\": \"已转正\", \"width\": 90, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"BOOLEAN\"}}, {\"field\": \"mobile\", \"label\": \"手机号\", \"width\": 130, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}, {\"field\": \"bill_status\", \"label\": \"状态\", \"width\": 110, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false, \"formatter\": {\"type\": \"TAG\", \"dictType\": \"test_demo_bill_status\"}}, {\"field\": \"remark\", \"label\": \"备注\", \"width\": 240, \"widthType\": \"min\", \"align\": \"left\", \"fixed\": false, \"sortable\": false}], \"searchItems\": [{\"field\": \"staff_no\", \"label\": \"工号\", \"widget\": \"TEXT\", \"operator\": \"LIKE\"}, {\"field\": \"staff_name\", \"label\": \"姓名\", \"widget\": \"TEXT\",