\\\\\\\"input\\\\\\\", \\\\\\\"field\\\\\\\": \\\\\\\"contract_name\\\\\\\", \\\\\\\"title\\\\\\\": \\\\\\\"合同名称\\\\\\\", \\\\\\\"$required\\\\\\\": true, \\\\\\\"_fc_id\\\\\\\": \\\\\\\"id_demo0004\\\\\\\", \\\\\\\"name\\\\\\\": \\\\\\\"ref_demo0004\\\\\\\", \\\\\\\"display\\\\\\\": true, \\\\\\\"hidden\\\\\\\": false, \\\\\\\"_fc_drag_tag\\\\\\\": \\\\\\\"input\\\\\\\", \\\\\\\"props\\\\\\\": {\\\\\\\"placeholder\\\\\\\": \\\\\\\"把它清空再提交 —— 报错来自内核的必填校验，beforeSubmit 根本没执行\\\\\\\"}}\\\",\\\"{\\\\\\\"type\\\\\\\": \\\\\\\"input\\\\\\\", \\\\\\\"field\\\\\\\": \\\\\\\"party_b\\\\\\\", \\\\\\\"title\\\\\\\": \\\\\\\"乙方\\\\\\\", \\\\\\\"$required\\\\\\\": true, \\\\\\\"_fc_id\\\\\\\": \\\\\\\"id_demo0005\\\\\\\", \\\\\\\"name\\\\\\\": \\\\\\\"ref_demo0005\\\\\\\", \\\\\\\"display\\\\\\\": true, \\\\\\\"hidden\\\\\\\": false, \\\\\\\"_fc_drag_tag\\\\\\\": \\\\\\\"input\\\\\\\"}\\\",\\\"{\\\\\\\"type\\\\\\\": \\\\\\\"input\\\\\\\", \\\\\\\"field\\\\\\\": \\\\\\\"owner_name\\\\\\\", \\\\\\\"title\\\\\\\": \\\\\\\"负责人\\\\\\\", \\\\\\\"$required\\\\\\\": true, \\\\\\\"_fc_id\\\\\\\": \\\\\\\"id_demo0006\\\\\\\", \\\\\\\"name\\\\\\\": \\\\\\\"ref_demo0006\\\\\\\", \\\\\\\"display\\\\\\\": true, \\\\\\\"hidden\\\\\\\": false, \\\\\\\"_fc_drag_tag\\\\\\\": \\\\\\\"input\\\\\\\"}\\\",\\\"{\\\\\\\"type\\\\\\\": \\\\\\\"select\\\\\\\", \\\\\\\"field\\\\\\\": \\\\\\\"bill_status\\\\\\\", \\\\\\\"title\\\\\\\": \\\\\\\"单据状态\\\\\\\", \\\\\\\"$required\\\\\\\": true, \\\\\\\"_fc_id\\\\\\\": \\\\\\\"id_demo0007\\\\\\\", \\\\\\\"name\\\\\\\": \\\\\\\"ref_demo0007\\\\\\\", \\\\\\\"display\\\\\\\": true, \\\\\\\"hidden\\\\\\\": false, \\\\\\\"_fc_drag_tag\\\\\\\": \\\\\\\"select\\\\\\\", \\\\\\\"props\\\\\\\": {\\\\\\\"dictSource\\\\\\\": {\\\\\\\"dictType\\\\\\\": \\\\\\\"test_demo_bill_status\\\\\\\", \\\\\\\"valueType\\\\\\\": \\\\\\\"str\\\\\\\"}}}\\\",\\\"{\\\\\\\"type\\\\\\\": \\\\\\\"fcTitle\\\\\\\", \\\\\\\"field\\\\\\\": \\\\\\\"g_money\\\\\\\", \\\\\\\"title\\\\\\\": \\\\\\\"二、金