INSERT INTO `system_notice` VALUES (5, 'AI 助手工作流功能上线', '<p>AI 助手新增「工作流」能力，支持把多步工具调用编排成可复用的流程，并在执行前预览计划。详见使用手册 AI 助手章节。</p>', 1, 0, '1', '2026-10-15 20:49:59', '1', '2026-10-15 20:49:59', b'0', 1);
INSERT INTO `system_notice` VALUES (6, '10 月系统维护窗口公告', '<p>本周六 22:00 - 24:00 进行数据库升级，期间系统不可用，请提前保存草稿。</p>', 2, 0, '1', '2026-10-15 20:49:59', '1', '2026-10-15 20:49:59', b'0', 1);
INSERT INTO `system_notice` VALUES (7, '旧版报表入口下线预告', '<p>旧版「统计报表」入口将于下月底下线，请改用「数据中心 → 报表」。</p>', 2, 1, '1', '2026-10-15 20:49:59', '1', '2026-10-15 20:49:59', b'0', 1);
