-- Table structure for graph_checkpoint
-- ----------------------------
DROP TABLE IF EXISTS `graph_checkpoint`;
CREATE TABLE `graph_checkpoint`  (
  `checkpoint_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `thread_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `next_node_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `state_data` json NOT NULL,
  `saved_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`checkpoint_id`) USING BTREE,
  INDEX `GRAPH_FK_THREAD`(`thread_id` ASC) USING BTREE,
  CONSTRAINT `GRAPH_FK_THREAD` FOREIGN KEY (`thread_id`) REFERENCES `graph_thread` (`thread_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

