-- Records of infra_data_interface_version
-- ----------------------------

-- ----------------------------
-- Table structure for infra_data_model
-- ----------------------------
DROP TABLE IF EXISTS `infra_data_model`;
CREATE TABLE `infra_data_model`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `data_source_config_id` bigint NOT NULL DEFAULT 0 COMMENT '数据源配置的编号',
  `table_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表名称',
  `table_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '表描述',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '模型名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `list_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '列表页配置 JSON：展示列、查询条件、默认排序',
  `form_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '表单配置 JSON：字段顺序、控件类型、校验规则',
  `sub_table_config` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '子表配置 JSON：子表名 + 外键字段',
  `column_meta` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '列的业务元数据 JSON：列名 → {dictType, refTable, refColumn}',
  `source` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '来源：MANUAL=人工在数据建模界面创建；AI=Agent 工具创建；IMPORT=导入已有表登记',
  `manual_edited_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否被人工手改过：AI 建的模型被人在界面上改动后置 1，治理动作只应作用于 0 的行',
  `schema_fingerprint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上次 DDL 成功时的表结构指纹（列名+类型+长度+可空+默认值的 sha256）。改表执行 DDL 前用它复核结构有没有被绕过平台改动；NULL=尚未记录基线',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号，由 MyBatis-Plus @Version 维护，更新时作为 WHERE 条件并自增',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_table_name`(`table_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 365 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '数据模型（受管表登记）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of infra_data_model
-- ----------------------------

-- ----------------------------
-- Table structure for infra_data_model_log
-- ----------------------------
DROP TABLE IF EXISTS `infra_data_model_log`;
CREATE TABLE `infra_data_model_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `data_source_config_id` bigint NOT NULL DEFAULT 0 COMMENT '数据源配置的编号',
  `table_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表名称',
  `operate_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型：CREATE / ALTER / DROP',
  `execute_sql` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实际执行的 DDL',
  `success` bit(1) NOT NULL COMMENT '是否执行成功',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '失败原因',
  `duration` int NOT NULL DEFAULT 0 COMMENT '执行耗时，单位：毫秒',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_table_name`(`table_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 155 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '数据模型 DDL 执行日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of infra_data_model_log
-- ----------------------------

