-- ----------------------------
-- Table structure for infra_form_design
-- ----------------------------
DROP TABLE IF EXISTS `infra_form_design`;
CREATE TABLE `infra_form_design`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单名称',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单编码，运行时与菜单引用它',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '分类，字典 infra_form_design_category',
  `form_type` tinyint NOT NULL DEFAULT 1 COMMENT '类型：1-纯表单 2-表单+列表',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-草稿 1-已发布 2-已发布有改动',
  `form_conf` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '表单配置 JSON，form-create 的 getOption()',
  `form_fields` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '表单字段规则 JSON 数组，form-create 的 getRule() 逐条序列化',
  `list_conf` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '列表配置 JSON：列/查询/按钮/树形/汇总/脚本',
  `data_source_config_id` bigint NULL DEFAULT 0 COMMENT '数据源编号，0 为主库，复用 infra_data_source_config',
  `main_table` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '主表名',
  `main_pk` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'id' COMMENT '主表主键列名',
  `table_binding` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '表绑定 JSON：字段映射/从表关联/子表配置',
  `schema_version` int NOT NULL DEFAULT 1 COMMENT '表单产物的 Schema 版本号。结构发生破坏性变更时递增，供迁移器判断如何升级',
  `published_version` int NULL DEFAULT 0 COMMENT '当前线上版本号，0 表示从未发布',
  `menu_id` bigint NULL DEFAULT NULL COMMENT '发布生成的菜单编号',
  `app_nav_node_id` bigint NULL DEFAULT NULL COMMENT 'App绔??鑸?妭鐐圭紪鍙?system_nav_node.id)锛孨ULL=鏈?彂甯冨埌App绔',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `source` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '来源：MANUAL=人工在设计器创建；AI=Agent 工具创建；IMPORT=导入登记（本表暂不使用该取值）',
  `manual_edited_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否被人工手改过：AI 建的表单被人在设计器改动后置 1，治理动作只应作用于 0 的行',
  `schema_fingerprint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发布时绑定的主表结构指纹（列名+类型+长度+可空+默认值的 sha256）。体检时对比现值，用于发现「发布后表结构被绕过平台改动」；NULL=尚未发布或未记录',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号，由 MyBatis-Plus @Version 维护，更新时作为 WHERE 条件并自增',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `logic_rules` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '联动规则 JSON 数组。声明式规则，见 LogicRule',
  `extension_mode` tinyint NOT NULL DEFAULT 1 COMMENT '扩展模式：0-无 1-前端脚本 2-服务端扩展点。互斥，同一表单只有一种生效',
  `form_script` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '前端脚本 JSON。仅 extension_mode=1 时执行',
  `submit_hook_timeout_action` tinyint NOT NULL DEFAULT 1 COMMENT 'beforeSubmit 超时后的动作：1-阻断 2-放行。默认阻断，超时即校验没跑完',
  `validate_rules` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '跨字段校验规则 JSON 数组。语义为 when 满足时 must 必须也满足，见 CrossFieldRule',
  `custom_buttons` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '自定义按钮 JSON 数组：[{key,label,icon,position,action,visibleWhen,permission}]',
  `detail_tabs` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '详情页页签 JSON 数组：[{key,label,type,...}]',
  `print_template` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '打印模板 HTML，占位符为 {字段}',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code` ASC) USING BTREE,
  INDEX `idx_category`(`category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 880517 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '表单设计定义' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of infra_form_design
-- ----------------------------

-- ----------------------------
-- Table structure for infra_form_design_data_log
-- ----------------------------
DROP TABLE IF EXISTS `infra_form_design_data_log`;
CREATE TABLE `infra_form_design_data_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `form_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单编码',
  `data_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务数据主键值。用字符串存 —— 主键可能是雪花、自增，也可能是 UUID',
  `changes` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '变更内容 JSON 数组：[{field,title,oldValue,newValue}]。用 mediumtext —— 一次改几十个字段、字段值又偏长时，text 的 64KB 并不宽裕',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者，即改动的人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间，即改动的时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_form_data`(`form_code` ASC, `data_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 353 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '表单数据变更日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of infra_form_design_data_log
