-- ----------------------------
-- Table structure for infra_portal
-- ----------------------------
DROP TABLE IF EXISTS `infra_portal`;
CREATE TABLE `infra_portal`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '门户名称',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '门户编码',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '门户描述',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '闂ㄦ埛绫诲瀷锛?-鍦ㄧ嚎璁捐? 1-鑷?畾涔夐摼鎺',
  `link_type` tinyint NULL DEFAULT NULL COMMENT '閾炬帴绫诲瀷锛?-椤甸潰锛堝唴閮ㄨ矾鐢憋級 1-澶栭摼',
  `link_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '閾炬帴鍦板潃',
  `sort` int NOT NULL DEFAULT 0 COMMENT '显示顺序（升序，值越小越靠前）',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-草稿 1-已发布 2-已发布有改动',
  `draft_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '草稿布局 JSON',
  `published_version` int NOT NULL DEFAULT 0 COMMENT '当前发布版本号',
  `is_default` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否为默认门户',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `visible_scope` tinyint NOT NULL DEFAULT 0 COMMENT '鍙??鑼冨洿锛?-鎵?湁浜?1-鎸囧畾瑙掕壊 2-鎸囧畾鐢ㄦ埛',
  `visible_ids` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鍙??瀵硅薄锛氳?鑹插瓨 code銆佺敤鎴峰瓨 id锛岄?鍙峰垎闅',
  `schema_version` int NOT NULL DEFAULT 1 COMMENT '布局协议版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_code`(`tenant_id` ASC, `code` ASC) USING BTREE,
  INDEX `idx_tenant_status`(`tenant_id` ASC, `status` ASC, `enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '门户设计定义' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of infra_portal
-- ----------------------------

